options.styles:
.orr-summary { margin: 0 0 12px; }
.orr-summary-h, .orr-chips-h {
  font-size: 10.5px; text-transform: uppercase; letter-spacing: .05em;
  color: #8e8e9e; margin-bottom: 6px;
}
.orr-sum-row { display: grid; grid-template-columns: 130px 1fr 110px; align-items: center; gap: 10px; margin: 6px 0; }
.orr-sum-lbl { font-size: 11px; color: #8e8e9e; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.orr-sum-val { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
.orr-sum-val i { font-style: normal; font-weight: 400; color: #8e8e9e; }

.orr-node { border: 1px solid #2c3235; border-radius: 3px; margin-bottom: 10px; }
.orr-node-h {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  padding: 8px 12px; border-bottom: 1px solid #2c3235; background: rgba(127, 127, 140, .08);
}
.orr-node-h b { font-size: 12.5px; }
.orr-node-h .orr-sp { margin-left: auto; font-size: 11px; color: #8e8e9e; }
.orr-pill { border: 1px solid #2c3235; border-radius: 4px; padding: 2px 8px; font-size: 10.5px; color: #8e8e9e; }
.orr-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; flex: none; }

.orr-conn { padding: 10px 12px; border-bottom: 1px solid rgba(127, 127, 140, .18); }
.orr-conn:last-child { border-bottom: 0; }
.orr-conn-h { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.orr-conn-h b { font-size: 12px; }
.orr-conn-h .orr-acct { font-size: 11px; color: #8e8e9e; }
.orr-conn-h .orr-min { margin-left: auto; font-size: 11.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
.orr-grid { display: grid; grid-template-columns: minmax(240px, 320px) 1fr; gap: 16px; }
@media (max-width: 700px) { .orr-grid { grid-template-columns: 1fr; } }

.orr-q { display: grid; grid-template-columns: 84px 1fr 46px; align-items: center; gap: 8px; margin: 5px 0; }
.orr-q span:first-child { font-size: 10.5px; color: #8e8e9e; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.orr-q b { font-size: 11px; text-align: right; font-variant-numeric: tabular-nums; }
.orr-track { height: 9px; border-radius: 2px; background: rgba(127, 127, 140, .25); overflow: hidden; }
.orr-fill { height: 100%; border-radius: 2px; }

.orr-chips { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }
.orr-chip {
  display: inline-flex; align-items: center; gap: 5px;
  border: 1px solid #2c3235; border-radius: 3px; padding: 2px 7px;
  font-size: 11px; font-family: ui-monospace, Menlo, Consolas, monospace;
}
.orr-chip.is-absent { color: #8e8e9e; }
.orr-err { font-size: 11px; color: #f2495c; }
.orr-muted { font-size: 11px; color: #8e8e9e; }
.orr-legend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 10.5px; color: #8e8e9e; padding-top: 4px; }
.orr-legend span { display: inline-flex; align-items: center; gap: 5px; }

options.afterRender:
/**
 * Рисует список «нода -> подключение провайдера -> квоты и модели».
 * Данные приходят четырьмя таргетами: A — orr_provider_quota_percent, B — orr_provider_quota_status,
 * C — orr_node_model_catalog, D — control.router_nodes (имена нод из Postgres).
 */
var COLORS = {
  ok: '#73bf69',
  warn: '#f2cc0c',
  bad: '#f2495c',
  absent: '#8e8e9e'
};

var series = (context.panelData && context.panelData.series) || [];

/** Значение поля дата-фрейма: в Grafana 10 values — обычный массив, в старых — ArrayVector. */
function valueAt(field, i) {
  var values = field.values;
  if (!values) return undefined;
  return typeof values.get === 'function' ? values.get(i) : values[i];
}

/** Строки всех фреймов одного таргета как массив объектов {имя поля: значение}. */
function rowsOf(refId) {
  var out = [];
  series.filter(function (frame) { return frame.refId === refId; }).forEach(function (frame) {
    var fields = frame.fields || [];
    var length = frame.length != null
      ? frame.length
      : (fields[0] && fields[0].values ? fields[0].values.length : 0);
    for (var i = 0; i < length; i++) {
      var row = {};
      fields.forEach(function (field) { row[field.name] = valueAt(field, i); });
      out.push(row);
    }
  });
  return out;
}

/** Prometheus зовёт колонку значения Value, но при нескольких фреймах имя может отличаться. */
function metricValue(row) {
  if (row.Value != null) return Number(row.Value);
  var key = Object.keys(row).filter(function (name) { return name.indexOf('Value') === 0; })[0];
  return key ? Number(row[key]) : NaN;
}

function esc(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function quotaColor(percent) {
  if (percent > 50) return COLORS.ok;
  if (percent > 20) return COLORS.warn;
  return COLORS.bad;
}

function fmt(percent) {
  return (Math.round(percent * 10) / 10).toFixed(1);
}

var quotaRows = rowsOf('A');
var statusRows = rowsOf('B');
var modelRows = rowsOf('C');
var nodeRows = rowsOf('D');

/* Подключения собираем из всех трёх метрик: сломанное подключение есть только в B,
   а подключение без моделей — только в A. Пропасть из списка не должно ни одно. */
var connections = {};
function connectionOf(row) {
  var key = [row.node_id, row.provider, row.connection_id].join('\u0000');
  if (!connections[key]) {
    connections[key] = {
      nodeId: row.node_id || 'unknown',
      provider: row.provider || 'unknown',
      connectionId: row.connection_id || 'unknown',
      account: '',
      quotas: [],
      models: [],
      reporting: true,
      reason: ''
    };
  }
  if (row.account_name) connections[key].account = row.account_name;
  return connections[key];
}

quotaRows.forEach(function (row) {
  var percent = metricValue(row);
  if (isNaN(percent)) return;
  connectionOf(row).quotas.push({ name: row.quota_name || 'total', percent: percent });
});

statusRows.forEach(function (row) {
  var connection = connectionOf(row);
  if (metricValue(row) === 0) {
    connection.reporting = false;
    connection.reason = row.reason || 'unknown';
  }
});

modelRows.forEach(function (row) {
  connectionOf(row).models.push({
    modelId: row.model_id || '',
    state: row.billing_state || 'absent'
  });
});

var STATE_ORDER = { enabled: 0, disabled: 1, absent: 2 };
var STATE_COLOR = { enabled: COLORS.ok, disabled: COLORS.warn, absent: COLORS.absent };

/* Именно через hasOwnProperty: у enabled вес 0, и привычное `order[state] || 3`
   отправляло бы включённые модели в конец списка. */
function stateOrder(state) {
  return Object.prototype.hasOwnProperty.call(STATE_ORDER, state) ? STATE_ORDER[state] : 3;
}

/** «1 подключение / 2 подключения / 5 подключений». */
function plural(count, one, few, many) {
  var mod100 = count % 100;
  if (mod100 >= 11 && mod100 <= 14) return count + ' ' + many;
  var mod10 = count % 10;
  if (mod10 === 1) return count + ' ' + one;
  if (mod10 >= 2 && mod10 <= 4) return count + ' ' + few;
  return count + ' ' + many;
}

var all = Object.keys(connections).map(function (key) { return connections[key]; });
all.forEach(function (connection) {
  connection.quotas.sort(function (a, b) { return a.name.localeCompare(b.name); });
  connection.models.sort(function (a, b) {
    var byState = stateOrder(a.state) - stateOrder(b.state);
    return byState !== 0 ? byState : a.modelId.localeCompare(b.modelId);
  });
  connection.min = connection.quotas.length
    ? Math.min.apply(null, connection.quotas.map(function (q) { return q.percent; }))
    : null;
});

/* Сводка: остаток подключения = min по его квотам, дальше сумма по провайдеру,
   потолок = (число подключений) * 100 %. */
var byProvider = {};
all.forEach(function (connection) {
  if (connection.min == null) return;
  if (!byProvider[connection.provider]) byProvider[connection.provider] = { sum: 0, count: 0 };
  byProvider[connection.provider].sum += connection.min;
  byProvider[connection.provider].count += 1;
});

var nodesById = {};
nodeRows.forEach(function (row) {
  nodesById[row.node_id] = {
    name: row.name || row.node_id,
    status: row.status || '',
    inFlight: row.in_flight_requests
  };
});

var html = [];

var providerNames = Object.keys(byProvider).sort();
if (providerNames.length) {
  html.push('<div class="orr-summary"><div class="orr-summary-h">Суммарный остаток по провайдерам</div>');
  providerNames.forEach(function (provider) {
    var totals = byProvider[provider];
    var ceiling = totals.count * 100;
    var share = ceiling > 0 ? (totals.sum / ceiling) * 100 : 0;
    var color = quotaColor(share);
    html.push(
      '<div class="orr-sum-row">' +
        '<div class="orr-sum-lbl">' + esc(provider) + ' &middot; ' + totals.count + ' подкл.</div>' +
        '<div class="orr-track"><div class="orr-fill" style="width:' + fmt(share) + '%;background:' + color + '"></div></div>' +
        '<div class="orr-sum-val" style="color:' + color + '">' + fmt(totals.sum) + '<i> / ' + ceiling + ' %</i></div>' +
      '</div>'
    );
  });
  html.push('</div>');
}

var nodeIds = all.map(function (connection) { return connection.nodeId; })
  .filter(function (id, index, list) { return list.indexOf(id) === index; })
  .sort(function (a, b) {
    var an = nodesById[a] ? nodesById[a].name : a;
    var bn = nodesById[b] ? nodesById[b].name : b;
    return an.localeCompare(bn);
  });

nodeIds.forEach(function (nodeId) {
  var node = nodesById[nodeId] || { name: nodeId, status: '', inFlight: null };
  var nodeConnections = all
    .filter(function (connection) { return connection.nodeId === nodeId; })
    .sort(function (a, b) {
      return a.provider.localeCompare(b.provider) || a.account.localeCompare(b.account);
    });

  var models = nodeConnections.reduce(function (acc, connection) { return acc + connection.models.length; }, 0);
  var enabled = nodeConnections.reduce(function (acc, connection) {
    return acc + connection.models.filter(function (model) { return model.state === 'enabled'; }).length;
  }, 0);
  var healthy = node.status === 'Healthy';

  html.push('<div class="orr-node">');
  html.push(
    '<div class="orr-node-h">' +
      '<span class="orr-dot" style="background:' + (healthy ? COLORS.ok : COLORS.bad) + '"></span>' +
      '<b>' + esc(node.name) + '</b>' +
      (node.status ? '<span class="orr-pill">' + esc(node.status) + '</span>' : '') +
      (node.inFlight != null ? '<span class="orr-pill">in-flight ' + esc(node.inFlight) + '</span>' : '') +
      '<span class="orr-sp">' +
        plural(nodeConnections.length, 'подключение', 'подключения', 'подключений') + ' &middot; ' +
        plural(models, 'модель', 'модели', 'моделей') + ' &middot; ' + enabled + ' включено</span>' +
    '</div>'
  );

  nodeConnections.forEach(function (connection) {
    html.push('<div class="orr-conn">');
    html.push(
      '<div class="orr-conn-h">' +
        '<b>' + esc(connection.provider) + '</b>' +
        '<span class="orr-acct">' + esc(connection.account || connection.connectionId) +
          ' &middot; conn ' + esc(connection.connectionId) + '</span>' +
        (connection.min != null
          ? '<span class="orr-min" style="color:' + quotaColor(connection.min) + '">min ' + fmt(connection.min) + '%</span>'
          : '') +
      '</div>'
    );
    html.push('<div class="orr-grid"><div>');
    html.push('<div class="orr-chips-h">Остаток лимитов</div>');

    if (!connection.reporting) {
      html.push('<div class="orr-err">квота не читается &middot; reason=' + esc(connection.reason) + '</div>');
    } else if (!connection.quotas.length) {
      html.push('<div class="orr-muted">нет данных по квотам</div>');
    } else {
      connection.quotas.forEach(function (quota) {
        var color = quotaColor(quota.percent);
        html.push(
          '<div class="orr-q">' +
            '<span>' + esc(quota.name) + '</span>' +
            '<div class="orr-track"><div class="orr-fill" style="width:' + fmt(Math.max(0, Math.min(100, quota.percent))) +
              '%;background:' + color + '"></div></div>' +
            '<b style="color:' + color + '">' + Math.round(quota.percent) + '%</b>' +
          '</div>'
        );
      });
    }

    html.push('</div><div>');
    var enabledHere = connection.models.filter(function (model) { return model.state === 'enabled'; }).length;
    html.push('<div class="orr-chips-h">Модели подключения' + (connection.models.length
      ? ' &middot; ' + enabledHere + ' из ' + connection.models.length + ' включено'
      : '') + '</div>');

    if (!connection.models.length) {
      html.push('<div class="orr-muted">нет данных каталога</div>');
    } else {
      html.push('<div class="orr-chips">' + connection.models.map(function (model) {
        var color = STATE_COLOR[model.state] || COLORS.absent;
        return '<span class="orr-chip' + (model.state === 'absent' ? ' is-absent' : '') + '" title="' + esc(model.state) + '">' +
          '<span class="orr-dot" style="width:7px;height:7px;background:' + color + '"></span>' +
          esc(model.modelId) + '</span>';
      }).join('') + '</div>');
    }

    html.push('</div></div></div>');
  });

  html.push('</div>');
});

if (!all.length) {
  html.push('<div class="orr-muted">Нет данных: коллектор ещё не опросил ноды либо метрики не скрейпятся.</div>');
}

html.push(
  '<div class="orr-legend">' +
    '<span><span class="orr-dot" style="background:' + COLORS.ok + '"></span>включена в ORR</span>' +
    '<span><span class="orr-dot" style="background:' + COLORS.warn + '"></span>есть в каталоге, выключена</span>' +
    '<span><span class="orr-dot" style="background:' + COLORS.absent + '"></span>нода отдаёт, в каталоге нет</span>' +
  '</div>'
);

context.element.innerHTML = html.join('');
